"use strict";(globalThis.webpackChunkdpkg_github_io||=[]).push([[130],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"hp-laserjet-1020-macos-driver","metadata":{"permalink":"/blog/hp-laserjet-1020-macos-driver","editUrl":"https://github.com/dpkg/dpkg.github.io/edit/develop/blog/2020-08-17-hp-laserjet-old-macos-driver.mdx","source":"@site/blog/2020-08-17-hp-laserjet-old-macos-driver.mdx","title":"Installing HP LaserJet 1020 driver on macOS!","description":"Installing driver for the old/legacy HP LaserJet 1020 printer on your macOS version. The drivers aren\'t supported by Apple, but HP has a support page for a lot of their old printers.","date":"2020-08-17T00:00:00.000Z","tags":[{"inline":true,"label":"deepakgiri","permalink":"/blog/tags/deepakgiri"},{"inline":true,"label":"macos","permalink":"/blog/tags/macos"},{"inline":true,"label":"printer","permalink":"/blog/tags/printer"},{"inline":true,"label":"general","permalink":"/blog/tags/general"}],"readingTime":1.73,"hasTruncateMarker":true,"authors":[{"name":"Deepak Giri","title":"Explorer","url":"https://github.com/dpkg","imageURL":"https://avatars1.githubusercontent.com/u/1250194?s=460&v=4","key":"deepak-giri","page":null}],"frontMatter":{"slug":"hp-laserjet-1020-macos-driver","title":"Installing HP LaserJet 1020 driver on macOS!","authors":["deepak-giri"],"tags":["deepakgiri","macos","printer","general"],"description":"Installing driver for the old/legacy HP LaserJet 1020 printer on your macOS version. The drivers aren\'t supported by Apple, but HP has a support page for a lot of their old printers.","image":"https://avatars1.githubusercontent.com/u/1250194?s=460&v=4","keywords":["deepakgiri","hp","hewlett packard","laserjet","1020","1022","printer","driver","apple","macos","catalina","deepak","giri"]},"unlisted":false,"nextItem":{"title":"Hello World","permalink":"/blog/hello-world"}},"content":"Apple used to provide drivers for download for some old models of HP LaserJet (and other) printers.\\n\\n\x3c!-- truncate --\x3e\\nBut it has now stopped supporting that, and you can now instead go to HPs [website](https://support.hp.com/us-en/drivers/selfservice/hp-laserjet-1022-printer-series/439424)\\nto download the drivers for some of their older models or LaserJet printers that are compatible with macOS operating systems.\\n\\n<p align=\\"center\\">\\n  <img alt=\\"hp laserjet 1020 printer\\" src=\\"https://ssl-product-images.www8-hp.com/digmedialib/prodimg/lowres/c03009416.png\\" />\\n</p>\\n\\nYou can click [this link](https://support.hp.com/us-en/drivers/printers) to get to the HP support page\\nwhere they\'ve listed the supported printer models and also the driver downloads.\\n\\nI have an old HP LaserJet 1020. Although it\'s not listed in the page above, it still works with the 1022 driver, that is listed\\n(I\'m guessing because they\'re the same series).\\n\\nI\'m listing the steps on how to install the LaserJet 1020 printer on macOS Catalina (10.15.6).\\n\\n1. Go to [this page](https://support.hp.com/us-en/drivers/selfservice/hp-laserjet-1022-printer-series/439424) and download the driver based on the macOS version you have.\\n2. After the download has finished, open the image file. Then double click on the content of the image file to install the drivers.\\n3. Once the driver installation has finished, connect your printer to your macbook and then turn it on.\\n4. Open \\"System Preferences\\", go to \\"Printers & Scanners\\", and then click the add (+) button below the list of printers on the left side.\\n5. Your printers should shop up in the Add window. Click it.\\n6. Now select the \\"Use\\" dropdown field and click \\"Select Printer Software\\" option. Search for your printer version (for 1020, search for 1022 and select that).\\n7. Press Add. And that\'s it.\\n\\nYour printer should now be all setup and ready to print! You can print a test page to confirm\\n(I\'ll suggest though directly printing what you want to print as a test, to avoid printing a fake page and wasting a sheet of paper)."},{"id":"hello-world","metadata":{"permalink":"/blog/hello-world","editUrl":"https://github.com/dpkg/dpkg.github.io/edit/develop/blog/2020-06-20-hello-world.md","source":"@site/blog/2020-06-20-hello-world.md","title":"Hello World","description":"Deepak Giri\'s first blog post on his personal website https://dpkg.in","date":"2020-06-20T00:00:00.000Z","tags":[{"inline":true,"label":"deepakgiri","permalink":"/blog/tags/deepakgiri"},{"inline":true,"label":"cvent","permalink":"/blog/tags/cvent"},{"inline":true,"label":"welcome","permalink":"/blog/tags/welcome"},{"inline":true,"label":"hello","permalink":"/blog/tags/hello"},{"inline":true,"label":"general","permalink":"/blog/tags/general"}],"readingTime":0.04,"hasTruncateMarker":false,"authors":[{"name":"Deepak Giri","title":"Explorer","url":"https://github.com/dpkg","imageURL":"https://avatars1.githubusercontent.com/u/1250194?s=460&v=4","key":"deepak-giri","page":null}],"frontMatter":{"slug":"hello-world","title":"Hello World","authors":["deepak-giri"],"tags":["deepakgiri","cvent","welcome","hello","general"],"description":"Deepak Giri\'s first blog post on his personal website https://dpkg.in","image":"https://avatars1.githubusercontent.com/u/1250194?s=460&v=4","keywords":["deepak","giri"]},"unlisted":false,"prevItem":{"title":"Installing HP LaserJet 1020 driver on macOS!","permalink":"/blog/hp-laserjet-1020-macos-driver"}},"content":"Welcome to my personal website <code>dpkg.in</code>!"}]}}')}}]);